from pathlib import Path
import json,hashlib,subprocess,datetime
root=Path('/opt/royal')
paths=['src/shared/arcadeCatalog.ts','src/shared/cosmicEscapeBets.ts','src/shared/luelonSlots.ts','src/shared/luelonSlotsModels.ts','src/shared/luelonSlotsLines.ts','src/shared/velvetReign.ts','src/shared/velvetReignHistory.ts','server/games/velvetMath.ts','server/games/velvetReign.ts','server/games/luelonSlots.ts','src/shared/caramelCarnival.ts','server/games/caramelCarnival.ts','src/shared/nitroRun.ts','server/games/nitroRun.ts','src/shared/memeOverload.ts','src/shared/lastConvoy.ts','server/games/lastConvoy.ts','src/shared/afterglow.ts','server/games/afterglow.ts','src/shared/neopolisMath.ts','src/shared/neopolisMathV1.ts','src/shared/neopolisMathV2.ts','src/shared/neopolis.ts','server/games/neopolis.ts','src/shared/draconaMath.ts','src/shared/draconaMathV1.ts','src/shared/dracona.ts','server/games/dracona.ts','server/demoExpansion.ts','server/commonGameWallet.ts','src/shared/crLeo.ts','server/games/crLeo.ts','server/games/vfair/plinko/plinko-math.ts','server/games/originals.ts']
paths += ['src/shared/originalGames.ts','server/games/vfair/plinko/plinko-multipliers.ts','server/games/rush/crash.ts','server/afterglowProgress.ts','server/demoWallet.ts','server/demoWalletRoutes.ts','server/finance/nile-game-runtime.ts','src/wallet/ExpansionClient.ts']
hashes={p:hashlib.sha256((root/p).read_bytes().replace(b'\r\n',b'\n')).hexdigest() for p in paths if (root/p).is_file()}
row=json.loads(subprocess.check_output(['docker','inspect','royal-game-1'],text=True))[0]
report={'verifiedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'method':'Read-only source hashes and running game image metadata. No player sessions, balances or environment values read.','mathSourceHashes':hashes,'gameImage':row['Image'],'sourceCommit':row['Config']['Labels'].get('org.opencontainers.image.revision'),'health':row['State'].get('Health',{}).get('Status')}
print(json.dumps(report))
